def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_no_build = v[:v.index('+')]
        else:
            v_no_build = v

        # Split off pre-release (everything after '-')
        if '-' in v_no_build:
            core_part = v_no_build[:v_no_build.index('-')]
            prerelease_part = v_no_build[v_no_build.index('-') + 1:]
        else:
            core_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease_identifiers = []
            for ident in identifiers:
                if ident.isdigit():
                    prerelease_identifiers.append((0, int(ident)))
                else:
                    prerelease_identifiers.append((1, ident))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(item):
        index, version_str = item
        major, minor, patch, prerelease_identifiers = parse_version(version_str)

        # For sorting: versions without pre-release come after versions with pre-release
        # So we use False for with pre-release, True for without
        has_prerelease = prerelease_identifiers is not None

        if has_prerelease:
            prerelease_key = (False, prerelease_identifiers)
        else:
            prerelease_key = (True,)

        return (major, minor, patch, prerelease_key, index)

    # Create list of (index, version) to maintain original order for equal precedence
    indexed_versions = [(i, v) for i, v in enumerate(versions)]

    # Sort using the comparison key
    sorted_versions = sorted(indexed_versions, key=compare_key)

    # Extract just the version strings
    return [v for _, v in sorted_versions]

